const portfoliosFallidos = [];
function validarCards(index = 0) {
  cy.get('.card.account-metrics-card').then($cards => {
    const totalCards = $cards.length;
    if (index >= totalCards) {
      if (portfoliosFallidos.length > 0) {
        const lista = portfoliosFallidos.join(', ');
        throw new Error(`❌ Los siguientes portfolios no pudieron ser validados correctamente: ${lista}`);
      } else {
        cy.log('✅ Validación completa y exitosa de todos los portfolios.');
      }
      return;
    }
    cy.get('.card.account-metrics-card').eq(index).then($card => {
      const $arrow = $card.find('svg.svg-inline--fa.fa-arrow-right');
      const nombreCard = $card.find('span.text-truncate').text().trim();
      if ($arrow.length > 0) {
        cy.wrap($arrow).click({
          force: true
        });
        cy.log(`🔍 Validando el portfolio: "${nombreCard}"`);
        // Validaciones dentro cada portfolio
        cy.get('div.loading-overlay').should('not.exist');
        cy.get('.sk-circle-fade').should('not.exist');
        cy.get('div.card-body').should('be.visible');
        cy.get('rect.highcharts-background').should('be.visible');
        cy.get('div.inner-component-backdrop').should('be.visible');
        cy.get('.sk-circle-fade').should('not.exist');
        cy.get('div.loading-overlay').should('not.exist');
        // Volver al menú para continuar con el siguiente portfolio
        cy.contains('Mis portfolios', {
          matchCase: false
        }).click();
        cy.ValidacionesMisPortfolios();
        validarCards(index + 1);
      } else {
        cy.log(`❌ El portfolio "${nombreCard}" no tiene el elemento "arrow" para poder ingresar al mismo.`);
        portfoliosFallidos.push(nombreCard);
        validarCards(index + 1);
      }
    });
  });
}
